const courseLessons = {};
for(const item of courseModules) {
  const source=courseEntries.filter(e=>e.moduleId===item.id),base=Math.floor(source.length/item.lessons),longer=source.length%item.lessons;
  let offset=0;
  for(let i=0;i<item.lessons;i++) {
    const entries=source.slice(offset,offset+base+(i<longer?1:0)),id=`m${item.id}-l${i+1}`;offset+=entries.length;
    courseLessons[id]={id,module:item.id,number:i+1,name:`Module ${item.id} · Урок ${i+1}`,entries,
      sections:[...new Set(entries.map(e=>e.source.section))],signature:`m${item.id}-v1:${entries.map(e=>e.id).join(',')}`};
  }
}
function entriesFor(id) {return courseLessons[id]?.entries || vocabulary[id];}
function tasksFor(id) {return courseLessons[id]?courseLessons[id].entries.map(e=>assemblyBank[id].find(t=>t.id===e.id)):assemblyBank[id];}

