function courseSentenceParts(task,answered) {
  const text=answered?task.text.replace('___',task.answer):task.text;
  const blank=task.text.indexOf('___');let offset=0;
  return (text.match(/___|[A-Za-z]+(?:[-'’][A-Za-z]+)*|[^A-Za-z_]+/g)||[]).map(word=>{
    const start=offset;offset+=word.length;
    if(word==='___' || !/^[A-Za-z]/.test(word) || task.lang!=='en') return {text:word};
    const key=word.toLowerCase();
    let override=task.hints?.[key];
    if(!answered && override?.phrase?.toLowerCase().includes(task.answer.toLowerCase())) override=null;
    const hint={...courseHintWords[key],...override,word};
    if(answered && start>=blank && start<blank+task.answer.length) {
      const entry=courseEntries.find(e=>e.id===task.id);
      // Compound answers are explained as a whole only after the answer is revealed.
      if(task.answer.includes(' ')) Object.assign(hint,{phrase:task.answer,kk:entry.kk.word,ru:entry.ru.word});
    }
    return {text:word,hint};
  });
}
