function assemblySentenceParts(task,answered=false) {
  // Keep the detailed, position-specific readings of the original English tasks.
  const old=sentenceBank[task.category]?.find(t=>t.id===task.id && t.lang==='en' && t.text===task.text);
  if(old) return legacySentenceParts(old,answered);
  const text=answered?task.text.replace('___',task.answer):task.text,blank=task.text.indexOf('___');let offset=0;
  const source=entriesFor(task.category).find(e=>e.id===task.id);
  const overrides=task.id.startsWith('m1-r')?courseContextHints[Number(source.source.number)] || {}:{};
  return (text.match(/___|[A-Za-z]+(?:[-'’][A-Za-z]+)*|[^A-Za-z_]+/g)||[]).map(word=>{
    const start=offset;offset+=word.length;
    if(word==='___' || !/^[A-Za-z]/.test(word)) return {text:word};
    const key=word.toLowerCase();let override={...overrides[key],...task.hints?.[key]};
    if(!answered && override.phrase?.toLowerCase().includes(task.answer.toLowerCase())) override={};
    const hint={...(articleHints[key]||assemblyHintWords[key]),...override,word};
    if(key==='to') {
      const next=(text.slice(offset).match(/___|[A-Za-z]+/g)||[])[0]?.toLowerCase();
      const verbs=new Set(courseEntries.filter(e=>e.source.pos==='v').map(e=>e.en.word.toLowerCase()));
      if(next==='___' || verbs.has(next))Object.assign(hint,{kk:'етістіктің бастапқы формасының белгісі',ru:'частица перед начальной формой глагола',note:'Здесь to вводит начальную форму глагола; отдельного буквального перевода обычно нет.'});
    }

    if(answered && start>=blank && start<blank+task.answer.length) {
      if(task.answer.includes(' ')) Object.assign(hint,{phrase:task.answer,kk:source.kk.word,ru:source.ru.word});
      else if(key===source.en.word.toLowerCase()) Object.assign(hint,{ipa:source.en.ipa,kk:source.kk.word,ru:source.ru.word});
    }
    const phrase=task.phrases?.find(p=>p.words.includes(key));
    if(phrase && (answered || !phrase.text.toLowerCase().includes(task.answer.toLowerCase())))
      Object.assign(hint,{phrase:phrase.text,kk:phrase.kk,ru:phrase.ru});
    return {text:word,hint};
  });
}
function sentenceParts(task,answered=false) {
  return task.format===2?assemblySentenceParts(task,answered):legacySentenceParts(task,answered);
}

const courseStorageKey='slovarium.course.v1';
function validSelection(value) {
  if(value?.mode!=='course') return {mode:'course',module:null,lesson:null,screen:'catalog'};
  const module=Number.isInteger(value.module) && courseModules.some(m=>m.id===value.module && m.ready)?value.module:null;
  const lesson=module && Object.hasOwn(courseLessons,value.lesson) && courseLessons[value.lesson].module===module?value.lesson:null;
  let screen=['catalog','lessons','lesson'].includes(value.screen)?value.screen:lesson?'lesson':module?'lessons':'catalog';
  if(!module) screen='catalog';
  if(screen==='lesson' && !lesson) screen=module?'lessons':'catalog';
  return {mode:'course',module,lesson:screen==='lesson'?lesson:null,screen};
}
function validScore(value,total) {
  return value && Number.isInteger(value.firstTryCorrect) && value.firstTryCorrect>=0 && value.firstTryCorrect<=total &&
    Number.isInteger(value.errors) && value.errors>=total-value.firstTryCorrect &&
    value.total===total ? {firstTryCorrect:value.firstTryCorrect,errors:value.errors,total} : null;
}
function validAssemblyScore(value,count,signature) {
  const score=validScore(value,count*2);
  if(!score || value.format!==2 || value.signature!==signature ||
    !Number.isInteger(value.englishFirstTry) || value.englishFirstTry<0 || value.englishFirstTry>count ||
    !Number.isInteger(value.translationFirstTry) || value.translationFirstTry<0 || value.translationFirstTry>count ||
    value.englishFirstTry+value.translationFirstTry!==score.firstTryCorrect) return null;
  return {...score,format:2,signature,englishFirstTry:value.englishFirstTry,translationFirstTry:value.translationFirstTry};
}
class CourseProgress {
  constructor(storage) {
    this.storage=storage;this.saved=true;this.loaded=false;this.selection={mode:'course',module:null,lesson:null,screen:'catalog'};this.results={};
    try {
      const raw=JSON.parse(storage.getItem(courseStorageKey));
      if(raw?.version===1 || raw?.version===2) {
        this.loaded=true;this.selection=validSelection(raw.selection);
        for(const [id,lesson] of Object.entries(courseLessons)) {
          const result=raw.results?.[id];if(result?.signature!==lesson.signature) continue;
          const count=lesson.entries.length,cards=validScore(result.cards,count*2);
          const sentences=validAssemblyScore(result.sentences,count,sentenceSignature(lesson));
          const legacySentences=validScore(result.legacySentences,count) ||
            (result.sentences?.format!==2?validScore(result.sentences,count):null);
          if(cards || sentences || legacySentences) this.results[id]={signature:lesson.signature,cards,sentences,legacySentences};
        }
      }
    } catch { /* Invalid or unavailable storage is ignored. */ }
    this.persist();
  }
  data() {return {version:2,selection:this.selection,results:this.results};}
  persist() {
    try {this.storage.setItem(courseStorageKey,JSON.stringify(this.data()));this.saved=true;}
    catch {this.saved=false;}
  }
  select(selection) {this.selection=validSelection(selection);this.persist();}
  record(id,level,score) {
    const lesson=courseLessons[id];if(!lesson || !['cards','sentences'].includes(level) || score.phase!=='complete') return;
    const count=lesson.entries.length,total=count*2;
    const candidate=level==='cards'?validScore({...score,total},total):
      validAssemblyScore({...score,total,format:2,signature:sentenceSignature(lesson)},count,sentenceSignature(lesson));
    if(!candidate) return;
    const result=this.results[id] || {signature:lesson.signature,cards:null,sentences:null,legacySentences:null},previous=result[level];
    if(previous && (previous.firstTryCorrect>candidate.firstTryCorrect ||
      (previous.firstTryCorrect===candidate.firstTryCorrect && previous.errors<=candidate.errors))) return;
    result[level]=candidate;this.results[id]=result;this.persist();
  }
}

const storageKey = 'slovarium.category';
function shuffle(items, random = Math.random) {
  const result = [...items];
  for (let i=result.length-1;i>0;i--) {
    const j=Math.floor(random()*(i+1));
    [result[i],result[j]]=[result[j],result[i]];
  }
  return result;
}
const walletStorageKey='slovarium.wallet.v1';
class SlovariWallet {
  constructor(storage) {
    this.storage=storage;this.saved=true;this.blocked=false;this.message='';
    this.state={version:1,words:[],sentences:[],exchanges:[]};this.raw=null;
    try {
      this.raw=storage.getItem(walletStorageKey);
      if(this.raw!==null) {
        const value=JSON.parse(this.raw);
        if(!this.valid(value)) throw Error('invalid');
        this.state=value;
      }
    } catch {
      this.saved=false;this.blocked=true;
      this.message='Кошелёк недоступен или данные повреждены. Данные не изменены. Восстановите доступ или сохранённые данные и обновите страницу.';
    }
  }
  valid(value) {
    const unique=(items,known)=>Array.isArray(items)&&items.every(id=>typeof id==='string'&&known.has(id))&&new Set(items).size===items.length;
    const words=new Set(courseEntries.map(e=>e.id)),sentences=new Set(assemblyTasks.map(t=>t.id));
    if(!value||value.version!==1||!unique(value.words,words)||!unique(value.sentences,sentences)||!Array.isArray(value.exchanges)) return false;
    let spent=0;
    for(const item of value.exchanges) {
      if(!item||!Number.isSafeInteger(item.amount)||item.amount<=0||item.amount%10!==0||typeof item.date!=='string'||!Number.isFinite(Date.parse(item.date)))return false;
      spent+=item.amount;
    }
    return Number.isSafeInteger(spent)&&spent<=value.words.length*10+value.sentences.length*20;
  }
  get earned() {return this.state.words.length*10+this.state.sentences.length*20;}
  get balance() {return this.earned-this.state.exchanges.reduce((sum,e)=>sum+e.amount,0);}
  commit(next) {
    if(this.blocked)return false;
    try {
      // A second tab must never overwrite newer rewards or an exchange.
      if(this.storage.getItem(walletStorageKey)!==this.raw)throw Error('changed');
      const raw=JSON.stringify(next);this.storage.setItem(walletStorageKey,raw);
      this.raw=raw;this.state=next;this.saved=true;return true;
    } catch {
      this.saved=false;this.blocked=true;
      this.message='Изменения кошелька не сохранены. Обмен недоступен. Проверьте хранилище и обновите страницу; в другой вкладке данные могли измениться.';
      return false;
    }
  }
  reward(kind,id) {
    if(this.blocked||!['words','sentences'].includes(kind))return;
    const known=kind==='words'?courseEntries:assemblyTasks;
    if(!known.some(item=>item.id===id))return;
    if(this.state[kind].includes(id)) {
      this.message=kind==='words'?'Отлично! Ты помнишь это слово':'Отлично! Ты помнишь это предложение';return;
    }
    const next={...this.state,[kind]:[...this.state[kind],id]};
    if(this.commit(next))this.message=kind==='words'?'+10 СЛОВАРИ!':'+20 СЛОВАРИ!';
  }
  exchange(expectedBalance) {
    if(this.blocked||!this.saved||this.balance<=0||expectedBalance!==this.balance)return false;
    const next={...this.state,exchanges:[...this.state.exchanges,{date:new Date().toISOString(),amount:this.balance}]};
    if(!this.commit(next))return false;
    this.message='Обмен сохранён. Учебные достижения остались.';return true;
  }
}

class WordGame {
  constructor(random = Math.random, onReward=()=>{}) { this.onReward=onReward; this.random=random; this.phase='home'; this.category=null; }
  start(category) {
    if (!Object.hasOwn(vocabulary, category) && !Object.hasOwn(courseLessons, category)) return;
    this.unlocked=false; this.sentenceGame=null;
    this.firstTryCorrect=0; this.errors=0;
    this.category=category; this.deck=shuffle(entriesFor(category),this.random); this.index=0; this.newCard();
  }
  newCard() {
    this.source=languages[Math.floor(this.random()*languages.length)];
    this.targets=shuffle(languages.filter(l=>l!==this.source),this.random);
    this.stage=0; this.stageErrors=0; this.cardErrors=0; this.cardFeedback=null; this.prepare();
  }
  prepare() {
    const lesson=courseLessons[this.category];
    if(!lesson) {
      const others=shuffle(vocabulary[this.category].filter(e=>e.id!==this.entry.id),this.random).slice(0,2);
      this.options=shuffle([this.entry,...others],this.random);this.phase='question';this.correct=null;return;
    }
    const candidates=lesson?[...shuffle(lesson.entries,this.random),...shuffle(courseEntries.filter(e=>e.moduleId===lesson.module),this.random)]:shuffle(entriesFor(this.category),this.random);
    const norm=v=>v.toLowerCase().replace(/[.,;!?«»()]/g,'').trim();
    const used=new Set([norm(this.entry[this.target].word)]);
    const equivalents=[['high','tall'],['great','brilliant','wonderful'],['creepy-crawly','insect'],['intelligent','clever','wise'],['exciting','entertaining','interesting'],['similar','alike','same'],['enormous','huge','big']];
    const group=equivalents.find(g=>g.includes(this.entry.en.word.toLowerCase())) || [this.entry.en.word.toLowerCase()];
    const others=[];
    for(const e of candidates) {
      const value=norm(e[this.target].word);
      if(used.has(value) || group.includes(e.en.word.toLowerCase()) || languages.some(l=>norm(e[l].word)===norm(this.entry[l].word)))continue;
      used.add(value);others.push(e);if(others.length===2)break;
    }
    this.options=shuffle([this.entry,...others],this.random); this.phase='question'; this.correct=null;
  }
  get entry() { return this.deck[this.index]; }
  get target() { return this.targets[this.stage]; }
  answer(id) {
    if(this.phase!=='question' || !this.options.some(e=>e.id===id)) return;
    this.correct=id===this.entry.id;
    if(this.correct) {
      if(this.stageErrors===0) this.firstTryCorrect++;
    } else {
      this.errors++; this.stageErrors++; this.cardErrors++;
    }
    if(this.correct && this.stage===1 && this.cardErrors===0)this.onReward('words',this.entry.id);
    this.cardFeedback={target:this.target,correct:this.correct};
    if(this.correct && this.stage===0) { this.stage=1; this.stageErrors=0; this.prepare(); return; }
    this.phase='feedback';
  }
  advance() {
    if(this.phase!=='feedback') return;
    if(!this.correct) { this.options=shuffle(this.options,this.random); this.phase='question'; this.correct=null; this.cardFeedback=null; return; }
    if(this.index===this.deck.length-1) { this.phase='complete'; this.unlocked=this.firstTryCorrect>=Math.ceil(0.8*this.deck.length*2); return; }
    this.index++; this.newCard();
  }
  startSentences() {
    if(!this.unlocked || !['complete','sentence-complete'].includes(this.phase)) return;
    this.sentenceGame=new SentenceGame(tasksFor(this.category),this.random,this.onReward);
    this.phase='sentences';
  }
  home() { this.phase='home'; this.unlocked=false; this.sentenceGame=null; }
}
for(const task of assemblyTasks) {
  if(/^m[2-9]-r/.test(task.id)) {
    const full=task.text.replace('___',task.answer).toLowerCase();task.hints={...task.hints};
    if(full.includes('like each other') || full.includes('i like'))task.hints.like={ipa:'laɪk',kk:'ұнату',ru:'нравиться'};
    if(full.includes('heat and light'))task.hints.light={ipa:'laɪt',kk:'жарық',ru:'свет'};
    if(task.id==='m6-r536')task.hints.present={ipa:'prɪˈzent',kk:'сыйға тарту',ru:'преподнести'};
    if(full.includes('own'))task.hints.own={ipa:'əʊn',kk:'өзінің',ru:'собственный'};
  }
  task.phrases=[];
  const full=task.text.replace('___',task.answer).toLowerCase();
  const phrases=[
    ['take off',['take','off'],'ұшып шығады','взлетают'],
    ['every single night',['every','single','night'],'әр түн сайын','каждую ночь'],
    ['every morning',['every','morning'],'күн сайын таңертең','каждое утро'],
    ['every sunday',['every','sunday'],'әр жексенбіде','каждое воскресенье'],
    ['looks like',['looks','like'],'ұқсайды','похож на'],
    ['next to me',['next','to','me'],'менің қасыма','рядом со мной'],
    ['at all',['at','all'],'мүлде','совсем'],
    ['left out',['left','out'],'қалдырылған','исключено'],
    ['made of',['made','of'],'жасалған','сделан из']
  ];
  for(const [text,words,kk,ru] of phrases)if(full.includes(text))task.phrases.push({text,words,kk,ru});
  // The verb 'leaves' means a mark is left here, not foliage.
  if(task.id==='m1-r068')task.hints={leaves:{ipa:'liːvz',kk:'қалдырады',ru:'оставляет'}};
  if(task.id==='m1-r066')task.hints={grow:{kk:'өседі',ru:'растут'}};
  if(task.id==='m1-r061')task.hints={the:{ipa:'ðə',note:'Определённый артикль: речь об участниках этой сцены. Отдельного перевода обычно нет.'}};
}
const courseContentIssues=[];
for(const item of courseModules) {
  const entries=courseEntries.filter(e=>e.moduleId===item.id),lessons=Object.values(courseLessons).filter(l=>l.module===item.id);
  for(const e of entries) {
    const task=assemblyTasks.find(t=>t.id===e.id);
    if(!e.prepared || !task || !task.translations?.kk?.text || !task.translations?.ru?.text)
      courseContentIssues.push(e.id);
    else if(assemblySentenceParts(task,true).some(p=>p.hint && (!p.hint.ipa || (!p.hint.note && (!p.hint.kk || !p.hint.ru)))))
      courseContentIssues.push(e.id);
  }
  item.ready=entries.length===item.count && lessons.length===item.lessons && !entries.some(e=>courseContentIssues.includes(e.id));
}
function sentenceWords(text) {
  return text.match(/[\p{L}\p{N}]+(?:[-’'][\p{L}\p{N}]+)*/gu) || [];
}
function wordKey(text) {return sentenceWords(text).map(w=>w.toLocaleLowerCase()).join(' ');}
function sentenceSignature(lesson) {
  const data=JSON.stringify(tasksFor(lesson.id).map(t=>[t.id,t.text,t.choices,t.translations]));
  let hash=2166136261;for(let i=0;i<data.length;i++)hash=Math.imul(hash^data.charCodeAt(i),16777619);
  return `assembly-v2:${lesson.signature}:${hash>>>0}`;
}
class SentenceGame {
  constructor(tasks,random=Math.random,onReward=()=>{}) {
    this.onReward=onReward;this.random=random;this.index=0;this.firstTryCorrect=0;this.englishFirstTry=0;this.translationFirstTry=0;this.errors=0;
    // The quota is exact per run; retries reuse the already assigned language.
    const langs=shuffle(Array.from({length:tasks.length},(_,i)=>i<tasks.length-2?'kk':'ru'),random);
    this.deck=shuffle(tasks,random).map((task,i)=>({...task,translationLang:langs[i]}));this.newTask();
  }
  get task() {return this.deck[this.index];}
  get translation() {return this.task.translations[this.task.translationLang];}
  newTask() {this.taskErrors=0;this.translationErrors=0;this.selected=[];this.tiles=[];this.lastChecked=null;this.message='';this.prepare();}
  prepare() {this.options=shuffle(this.task.choices,this.random);this.phase='question';this.correct=null;}
  answer(value) {
    if(this.phase!=='question' || !this.options.includes(value)) return;
    this.correct=value===this.task.answer;
    if(!this.correct) {this.errors++;this.taskErrors++;this.phase='feedback';return;}
    if(this.taskErrors===0) {this.englishFirstTry++;this.firstTryCorrect++;}
    this.tiles=sentenceWords(this.translation.text).map((text,id)=>({id,text}));
    this.pool=shuffle(this.tiles.map(t=>t.id),this.random);
    // A shuffled exercise must not accidentally be the solved exercise.
    const solved=ids=>this.translation.variants.some(v=>wordKey(v)===wordKey(ids.map(id=>this.tiles[id].text).join(' ')));
    if(solved(this.pool)) {
      const initial=[...this.pool];let found=false;
      for(let i=0;i<initial.length && !found;i++) for(let j=i+1;j<initial.length && !found;j++) {
        const candidate=[...initial];[candidate[i],candidate[j]]=[candidate[j],candidate[i]];
        if(!solved(candidate)) {this.pool=candidate;found=true;}
      }
    }
    this.phase='translation';this.correct=null;
  }
  pick(id) {
    if(this.phase!=='translation' || !this.pool.includes(id)) return;
    this.pool=this.pool.filter(item=>item!==id);this.selected.push(id);this.edited();
  }
  remove(id) {
    if(this.phase!=='translation' || !this.selected.includes(id)) return;
    this.selected=this.selected.filter(item=>item!==id);this.pool.push(id);this.edited();
  }
  clear() {
    if(this.phase!=='translation' || !this.selected.length) return;
    this.pool.push(...this.selected);this.selected=[];this.edited();
  }
  edited() {this.message='';this.correct=null;}
  get assembled() {return this.selected.map(id=>this.tiles[id].text).join(' ');}
  get canCheck() {return this.phase==='translation' && this.selected.length===this.tiles.length && wordKey(this.assembled)!==this.lastChecked;}
  check() {
    if(!this.canCheck) return;
    const value=wordKey(this.assembled);this.lastChecked=value;
    const match=this.translation.variants.find(v=>wordKey(v)===value);
    this.correct=Boolean(match);
    if(!match) {this.errors++;this.translationErrors++;this.message='Попробуй ещё раз';return;}
    if(this.translationErrors===0) {this.translationFirstTry++;this.firstTryCorrect++;}
    if(this.taskErrors===0 && this.translationErrors===0)this.onReward('sentences',this.task.id);
    this.completedText=match;this.phase='translated';this.message='Верно!';
  }
  advance() {
    if(this.phase==='feedback') {this.prepare();return;}
    if(this.phase!=='translated') return;
    if(this.index===this.deck.length-1) {this.phase='complete';return;}
    this.index++;this.newTask();
  }
}

function loadCategory(storage) {
  try { const id=storage.getItem(storageKey); return Object.hasOwn(categories,id)?id:null; } catch { return null; }
}
function saveCategory(storage, id) { try { storage.setItem(storageKey,id); } catch { /* Browser storage may be disabled. */ } }

function wordWithIPA(variant) {
  return variant.word + (variant.ipa ? ` /${variant.ipa}/` : '');
}

function createSentenceHelp(doc, view, sentence, tip) {
  let active=null, hovered=null, overTip=false, focused=null, pinned=false, timer=null;
  function cancelClose() { view.clearTimeout(timer); }
  function close() {
    cancelClose();
    if(active) active.removeAttribute('aria-describedby');
    active=null; hovered=null; overTip=false; focused=null; pinned=false;
    tip.hidden=true; tip.replaceChildren();
  }
  function position() {
    if(!active || tip.hidden) return;
    const edge=8,gap=8,anchor=active.getBoundingClientRect();
    const width=doc.documentElement.clientWidth,height=view.innerHeight;
    tip.style.maxHeight=`${Math.max(44,height-edge*2)}px`;
    const box=tip.getBoundingClientRect();
    const left=Math.max(edge,Math.min(anchor.left+anchor.width/2-box.width/2,width-box.width-edge));
    let top=anchor.top-box.height-gap;
    if(top<edge) top=anchor.bottom+gap;
    top=Math.max(edge,Math.min(top,height-box.height-edge));
    tip.style.left=`${left}px`;tip.style.top=`${top}px`;
  }
  function show(button,hint) {
    cancelClose();
    if(active===button && !tip.hidden) return;
    close();active=button;
    function line(text,lang) {
      const p=doc.createElement('p');p.textContent=text;
      if(lang) p.lang=lang;
      tip.append(p);
    }
    line(`${hint.word} /${hint.ipa}/`,'en');
    if(hint.phrase) line(`Сочетание: ${hint.phrase}`);
    if(hint.kk) line(`Қазақша: ${hint.kk}`,'kk');
    if(hint.ru) line(`Русский: ${hint.ru}`,'ru');
    if(hint.phrase) line(`Пояснение: перевод относится ко всему сочетанию ${hint.phrase}.`);
    if(hint.note) line(`Пояснение: ${hint.note}`);
    button.setAttribute('aria-describedby',tip.id);
    tip.hidden=false;position();
  }
  function scheduleClose() {
    cancelClose();
    timer=view.setTimeout(()=>{
      if(!hovered && !overTip && !focused && !pinned) close();
    },180);
  }
  function render(task,answered) {
    close();
    sentence.replaceChildren();
    if(task.lang!=='en') {sentence.textContent=answered?task.text.replace('___',task.answer):task.text;return;}
    for(const part of sentenceParts(task,answered)) {
      if(!part.hint) {sentence.append(doc.createTextNode(part.text));continue;}
      const button=doc.createElement('button');
      button.type='button';button.className='sentence-word';button.lang='en';button.textContent=part.text;
      let pointerKind=null, wasOpen=false;
      button.addEventListener('pointerdown',event=>{
        pointerKind=event.pointerType;wasOpen=active===button && !tip.hidden;
      });
      button.addEventListener('pointerenter',event=>{
        if(event.pointerType==='touch') return;
        show(button,part.hint);hovered=button;cancelClose();
      });
      button.addEventListener('pointerleave',event=>{
        if(event.pointerType==='touch') return;
        if(hovered===button) hovered=null;
        scheduleClose();
      });
      button.addEventListener('focus',()=>{
        if(pointerKind) return;
        show(button,part.hint);focused=button;
      });
      button.addEventListener('blur',()=>{
        pointerKind=null;
        if(focused===button) focused=null;
        scheduleClose();
      });
      button.addEventListener('click',()=>{
        // Pointerdown runs before focus: touch focus must not toggle the first tap closed.
        if(pointerKind==='touch' || pointerKind==='pen') {
          if(wasOpen) close();
          else {show(button,part.hint);pinned=true;}
        } else if(!pointerKind) {show(button,part.hint);focused=button;}
        else {show(button,part.hint);hovered=button;}
        pointerKind=null;
      });
      sentence.append(button);
    }
  }
  tip.addEventListener('pointerenter',event=>{
    if(event.pointerType==='touch') return;
    overTip=true;cancelClose();
  });
  tip.addEventListener('pointerleave',event=>{
    if(event.pointerType==='touch') return;
    overTip=false;scheduleClose();
  });
  doc.addEventListener('pointerdown',event=>{
    if(active && !active.contains(event.target) && !tip.contains(event.target)) close();
  });
  doc.addEventListener('keydown',event=>{
    if(event.key==='Escape' && active) {event.preventDefault();close();}
  });
  view.addEventListener('resize',position);
  view.addEventListener('scroll',position,true);
  return {render,close};
}

